import{randomInt,randomUUID}from'node:crypto';import{Router,type NextFunction,type Request,type Response}from'express';import{z}from'zod';import{db}from'../database/db.js';import{normalizeCpf,validCpf}from'../cpf.js';import{canonicalizePassword,hashPassword,hashToken,newToken,secureStringEqual,verifyPassword}from'../security.js';import{clearLoginRateLimit,loginRateLimit,recordRateLimitedAttempt}from'../rate-limit.js';import{recordAccess}from'../access-log.js';import{releaseExpiredOfferReservations}from'../offer-reservations.js';
import{PLAN_FEATURES,tenantPlan}from'../plan-catalog.js';
import{customerVipTier,redemptionLimit}from'../loyalty.js';
import{clearSessionCookie,createSecureSession,platformMfaRequired,touchSession}from'../session-security.js';import{decryptTotp,encryptTotp,newTotpSecret,totpUri,verifyTotp}from'../two-factor.js';
import{config}from'../config.js';
export const portalRoutes=Router();
const TERMS_VERSION='2026-08-22',PRIVACY_VERSION='2026-08-22';
function customerAuth(req:Request,res:Response,next:NextFunction){const token=req.cookies?.fideliza_customer_session;if(!token)return res.status(401).json({error:'Cliente não autenticado'});const row=db.prepare(`SELECT ca.id accountId,ca.tenant_id tenantId,ca.customer_id customerId,c.name,t.name companyName,t.slug FROM customer_sessions cs JOIN customer_accounts ca ON ca.id=cs.account_id JOIN customers c ON c.id=ca.customer_id JOIN tenants t ON t.id=ca.tenant_id LEFT JOIN subscriptions s ON s.tenant_id=t.id WHERE cs.token_hash=? AND cs.expires_at>datetime('now') AND ca.active=1 AND c.deleted_at IS NULL AND COALESCE(t.login_blocked,0)=0 AND COALESCE(t.customer_portal_enabled,0)=1 AND COALESCE(s.status,'trialing') IN ('active','trialing')`).get(hashToken(token))as any;if(!row)return res.status(401).json({error:'Sessão do cliente inválida ou programa indisponível'});touchSession('customer_sessions',token);(req as any).customerAuth=row;next()}
function platformAuth(req:Request,res:Response,next:NextFunction){const token=req.cookies?.fideliza_platform_session;if(!token)return res.status(401).json({error:'Administrador não autenticado'});const row=db.prepare(`SELECT pa.id adminId,pa.name,pa.email,pa.role,pa.two_factor_enabled twoFactorEnabled FROM platform_sessions ps JOIN platform_admins pa ON pa.id=ps.admin_id WHERE ps.token_hash=? AND ps.expires_at>datetime('now') AND pa.active=1`).get(hashToken(token))as any;if(!row)return res.status(401).json({error:'Sessão administrativa inválida'});touchSession('platform_sessions',token);(req as any).platformAuth=row;next()}
function session(table:string,_column:string,id:string,res:Response,_cookieName:string){createSecureSession(table==='platform_sessions'?'platform':'customer',id,res.req,res)}
function normalizeBrazilPhone(value:string){const digits=value.replace(/\D/g,'');return digits.startsWith('55')&&digits.length>11?digits.slice(2):digits}
function customerOffersPlan(req:Request,res:Response,next:NextFunction){const plan=tenantPlan((req as any).customerAuth.tenantId);if(plan&&!plan.features.includes(PLAN_FEATURES.OFFERS))return res.status(403).json({error:'As ofertas exclusivas não estão incluídas no plano desta loja.',code:'PLAN_UPGRADE_REQUIRED'});next()}
const businessDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function availableCustomerRewards(tenantId:string,customerId:string){const tierRank=customerVipTier(tenantId,customerId)?.current?.rank??0,today=businessDate();return db.prepare(`SELECT id,name,description,points_cost,reward_type,image_data,product_sku,discount_type,discount_value,minimum_order_cents,valid_from,valid_until,minimum_tier_rank FROM rewards WHERE tenant_id=? AND active=1 AND reward_type='coupon' AND (valid_from IS NULL OR valid_from<=?) AND (valid_until IS NULL OR valid_until>=?) AND COALESCE(minimum_tier_rank,0)<=? ORDER BY points_cost`).all(tenantId,today,today,tierRank)}
portalRoutes.use('/customer/store-offers',customerAuth,customerOffersPlan);
portalRoutes.use('/customer/rewards/:id/redeem',customerAuth,(req,res,next)=>{const a=(req as any).customerAuth,limit=redemptionLimit(a.tenantId,a.customerId);if(!limit.allowed)return res.status(429).json({error:'Limite diário de resgates atingido. Tente novamente amanhã ou solicite análise da loja.',limit:limit.limit});next()});
portalRoutes.get('/customer/stores',(req,res)=>{const search=String(req.query.search||'').trim().slice(0,80),like=`%${search}%`;const stores=db.prepare(`SELECT t.name,t.slug,t.segment,t.logo_data logoData FROM tenants t LEFT JOIN subscriptions s ON s.tenant_id=t.id WHERE COALESCE(t.login_blocked,0)=0 AND COALESCE(t.customer_portal_enabled,0)=1 AND COALESCE(s.status,'trialing') IN ('active','trialing') AND (?='' OR t.name LIKE ? OR t.slug LIKE ?) ORDER BY t.name LIMIT 50`).all(search,like,like);res.json(stores)});
portalRoutes.get('/customer/store/:slug',(req,res)=>{const store=db.prepare(`SELECT t.id,t.name,t.slug,t.logo_data FROM tenants t LEFT JOIN subscriptions s ON s.tenant_id=t.id WHERE t.slug=? AND COALESCE(t.login_blocked,0)=0 AND COALESCE(t.customer_portal_enabled,0)=1 AND COALESCE(s.status,'trialing') IN ('active','trialing')`).get(String(req.params.slug));if(!store)return res.status(404).json({error:'Empresa não encontrada ou programa indisponível'});const recoveryChannels=['email'];if(process.env.WHATSAPP_ACCESS_TOKEN&&process.env.WHATSAPP_PHONE_NUMBER_ID)recoveryChannels.push('whatsapp');res.json({...store as object,recoveryChannels})});
portalRoutes.use(['/customer/auth/register','/customer/auth/reset-password','/customer/auth/reset-password-code'],(req,res,next)=>{if(req.body&&typeof req.body.password==='string'){req.body.password=canonicalizePassword(req.body.password);if(!/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{10,}$/.test(req.body.password))return res.status(400).json({error:'Use uma senha com no mínimo 10 caracteres, incluindo letra maiúscula, letra minúscula e número'});}next()});
const maskEmail=(value:string)=>{const[user='',domain='']=value.split('@');return `${user.slice(0,2)}***@${domain}`};
const maskPhone=(value:string)=>`(**) *****-${value.replace(/\D/g,'').slice(-4)}`;
class RegistrationError extends Error{constructor(message:string,readonly customerId?:string){super(message)}}
/**
 * Um CPF já cadastrado pela loja (PDV, ERP, importação) só ganha acesso ao portal depois que o
 * titular confirma um código enviado ao contato que a loja já tinha. Sem isso, quem conhecesse o
 * CPF assumiria o saldo e os dados do cliente.
 */
portalRoutes.post('/customer/auth/register',loginRateLimit,(req,res)=>{const p=z.object({tenantSlug:z.string().min(2),name:z.string().min(2),cpf:z.string().min(11),phone:z.string().min(10),email:z.string().email(),password:z.string().min(10),acceptTerms:z.literal(true),verificationCode:z.string().regex(/^\d{6}$/).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Preencha nome, CPF, telefone, e-mail válido, senha e aceite os termos'});const cpf=normalizeCpf(p.data.cpf),phone=p.data.phone.replace(/\D/g,'');if(!validCpf(cpf)||phone.length<10)return res.status(400).json({error:'CPF ou telefone inválido'});const tenant=db.prepare(`SELECT t.id,t.name,p.consumer_limit consumerLimit,(SELECT COUNT(*) FROM customers c WHERE c.tenant_id=t.id AND c.deleted_at IS NULL) consumers FROM tenants t LEFT JOIN subscriptions s ON s.tenant_id=t.id LEFT JOIN platform_plans p ON p.code=s.plan_code WHERE t.slug=? AND COALESCE(t.login_blocked,0)=0 AND COALESCE(t.customer_portal_enabled,0)=1 AND COALESCE(s.status,'trialing') IN ('active','trialing')`).get(p.data.tenantSlug)as{id:string;name:string;consumerLimit:number;consumers:number}|undefined;if(!tenant)return res.status(404).json({error:'Empresa não encontrada ou programa indisponível'});
  try{
    const result=db.transaction(()=>{
      let customer=db.prepare('SELECT id,email,phone FROM customers WHERE tenant_id=? AND cpf=?').get(tenant.id,cpf)as{id:string;email:string|null;phone:string|null}|undefined;
      if(customer&&db.prepare('SELECT id FROM customer_accounts WHERE tenant_id=? AND customer_id=?').get(tenant.id,customer.id))throw new RegistrationError('ACCOUNT');
      if(!customer){
        if(tenant.consumerLimit!==null&&tenant.consumerLimit!==undefined&&tenant.consumers>=tenant.consumerLimit)throw new RegistrationError('LIMIT');
        customer={id:randomUUID(),email:null,phone:null};
        db.prepare("INSERT INTO customers (id,tenant_id,name,email,phone,cpf,enrolled_at,status) VALUES (?,?,?,?,?,?,CURRENT_TIMESTAMP,'active')").run(customer.id,tenant.id,p.data.name,p.data.email.toLowerCase(),phone,cpf);
      }else{
        const channel=customer.email?'email':customer.phone&&process.env.WHATSAPP_ACCESS_TOKEN&&process.env.WHATSAPP_PHONE_NUMBER_ID?'whatsapp':null;
        if(!channel)throw new RegistrationError('NO_CONTACT');
        if(!p.data.verificationCode){
          const code=String(randomInt(100000,1000000)),recipient=channel==='email'?customer.email!:customer.phone!;
          db.prepare('UPDATE customer_registration_codes SET used_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND customer_id=? AND used_at IS NULL').run(tenant.id,customer.id);
          db.prepare("INSERT INTO customer_registration_codes(id,tenant_id,customer_id,code_hash,channel,expires_at)VALUES(?,?,?,?,?,datetime('now','+10 minutes'))").run(randomUUID(),tenant.id,customer.id,hashToken(code),channel);
          db.prepare("INSERT INTO outbound_messages(id,tenant_id,recipient,channel,template,subject,message,scheduled_at)VALUES(?,?,?,?,'customer.registration_code',?,?,CURRENT_TIMESTAMP)").run(randomUUID(),tenant.id,recipient,channel,`Código de confirmação · ${tenant.name}`,channel==='whatsapp'?code:`Seu código para ativar o acesso ao programa de fidelidade ${tenant.name} é ${code}. Ele vale por 10 minutos.\n\nSe você não pediu este acesso, ignore esta mensagem e avise a loja.`);
          return{verification:{channel,destination:channel==='email'?maskEmail(recipient):maskPhone(recipient)},code};
        }
        const pending=db.prepare("SELECT id,code_hash FROM customer_registration_codes WHERE tenant_id=? AND customer_id=? AND used_at IS NULL AND expires_at>datetime('now') AND attempts<5 ORDER BY created_at DESC LIMIT 1").get(tenant.id,customer.id)as{id:string;code_hash:string}|undefined;
        if(!pending||!secureStringEqual(pending.code_hash,hashToken(p.data.verificationCode)))throw new RegistrationError('CODE',customer.id);
        db.prepare('UPDATE customer_registration_codes SET used_at=CURRENT_TIMESTAMP WHERE id=?').run(pending.id);
        db.prepare("UPDATE customers SET name=?,email=?,phone=?,enrolled_at=COALESCE(enrolled_at,CURRENT_TIMESTAMP),deleted_at=NULL,status='active',updated_at=CURRENT_TIMESTAMP WHERE id=? AND tenant_id=?").run(p.data.name,p.data.email.toLowerCase(),phone,customer.id,tenant.id);
      }
      const id=randomUUID();db.prepare('INSERT INTO customer_accounts (id,tenant_id,customer_id,password_hash) VALUES (?,?,?,?)').run(id,tenant.id,customer.id,hashPassword(p.data.password));db.prepare("INSERT INTO customer_consents (id,tenant_id,customer_id,purpose,granted,source,document_version,privacy_version,ip_address,user_agent) VALUES (?,?,?,'loyalty',1,'customer_portal',?,?,?,?)").run(randomUUID(),tenant.id,customer.id,TERMS_VERSION,PRIVACY_VERSION,req.ip||null,String(req.headers['user-agent']||'').slice(0,500)||null);db.prepare("INSERT INTO outbound_messages(id,tenant_id,recipient,channel,template,subject,message,scheduled_at) VALUES (?,?,?,'email','customer.welcome',?,?,CURRENT_TIMESTAMP)").run(randomUUID(),tenant.id,p.data.email.toLowerCase(),`Bem-vindo à ${tenant.name}`,`Olá, ${p.data.name}. Seu cadastro no programa de fidelidade da ${tenant.name} foi realizado com sucesso. A partir de agora, compras identificadas pelo seu CPF podem gerar pontos e benefícios. Consulte as regras e sua privacidade em https://fidelizaplus.com.br/termos-programa e https://fidelizaplus.com.br/privacidade. Dúvidas: contato@fidelizaplus.com.br.`);return{accountId:id};
    })();
    if('verification' in result){recordRateLimitedAttempt(req,cpf,'registration_code_request');return res.status(202).json({verificationRequired:true,...result.verification,...(!config.isProduction?{developmentCode:result.code}:{})})}
    session('customer_sessions','account_id',result.accountId,res,'fideliza_customer_session');res.status(201).json({ok:true});
  }catch(e){const error=e as RegistrationError;if(error.message==='CODE'){db.prepare("UPDATE customer_registration_codes SET attempts=attempts+1 WHERE id=(SELECT id FROM customer_registration_codes WHERE tenant_id=? AND customer_id=? AND used_at IS NULL ORDER BY created_at DESC LIMIT 1)").run(tenant.id,error.customerId);recordRateLimitedAttempt(req,cpf,'invalid_registration_code');return res.status(400).json({error:'Código de confirmação inválido ou expirado. Peça um novo código.'})}if(error.message==='NO_CONTACT')return res.status(409).json({error:'Seu CPF já está no programa desta loja, mas sem e-mail ou telefone para confirmar a identidade. Procure a loja para atualizar o cadastro e liberar o acesso.'});if(error.message==='ACCOUNT')return res.status(409).json({error:'Este CPF já possui acesso. Entre com sua senha.'});if(error.message==='LIMIT')return res.status(409).json({error:'A loja atingiu o limite de consumidores do plano. Entre em contato com ela.'});return res.status(409).json({error:'Não foi possível concluir o cadastro'})}
});
portalRoutes.post('/customer/auth/login',loginRateLimit,(req,res)=>{const p=z.object({tenantSlug:z.string(),cpf:z.string(),password:z.string().min(8)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Dados inválidos'});const row=db.prepare(`SELECT ca.id,ca.password_hash,ca.tenant_id FROM customer_accounts ca JOIN customers c ON c.id=ca.customer_id JOIN tenants t ON t.id=ca.tenant_id LEFT JOIN subscriptions s ON s.tenant_id=t.id WHERE t.slug=? AND c.cpf=? AND ca.active=1 AND c.deleted_at IS NULL AND COALESCE(t.login_blocked,0)=0 AND COALESCE(t.customer_portal_enabled,0)=1 AND COALESCE(s.status,'trialing') IN ('active','trialing')`).get(p.data.tenantSlug,normalizeCpf(p.data.cpf))as any;if(!row||!verifyPassword(p.data.password,row.password_hash)){recordAccess(req,'customer',normalizeCpf(p.data.cpf),false,row?.tenant_id,'Credencial inválida ou programa indisponível');return res.status(401).json({error:'CPF ou senha inválidos'});}clearLoginRateLimit(req);db.prepare('UPDATE customer_accounts SET last_login_at=CURRENT_TIMESTAMP WHERE id=?').run(row.id);recordAccess(req,'customer',row.id,true,row.tenant_id);session('customer_sessions','account_id',row.id,res,'fideliza_customer_session');res.json({ok:true})});
portalRoutes.post('/customer/auth/forgot-password',loginRateLimit,(req,res)=>{
  const parsed=z.object({tenantSlug:z.string().min(2),cpf:z.string().min(11),channel:z.enum(['email','whatsapp']).default('email'),email:z.string().email().optional(),phone:z.string().min(10).optional(),consentWhatsApp:z.boolean().optional()}).safeParse(req.body);
  const channel=parsed.success?parsed.data.channel:'email';
  const message=channel==='whatsapp'?'Se os dados estiverem cadastrados, enviaremos um código pelo WhatsApp válido por 10 minutos.':'Se os dados estiverem cadastrados, enviaremos um link por e-mail válido por 30 minutos.';
  if(!parsed.success)return res.status(202).json({message,channel});
  if((channel==='email'&&!parsed.data.email)||(channel==='whatsapp'&&(!parsed.data.phone||!parsed.data.consentWhatsApp)))return res.status(202).json({message,channel});
  const cpf=normalizeCpf(parsed.data.cpf);
  recordRateLimitedAttempt(req,cpf,'password_reset_request');
  const row=db.prepare(`SELECT ca.id accountId,ca.tenant_id tenantId,c.id customerId,c.email,c.phone,t.slug,t.name companyName FROM customer_accounts ca JOIN customers c ON c.id=ca.customer_id JOIN tenants t ON t.id=ca.tenant_id LEFT JOIN subscriptions s ON s.tenant_id=t.id WHERE t.slug=? AND c.cpf=? AND ca.active=1 AND c.deleted_at IS NULL AND COALESCE(t.login_blocked,0)=0 AND COALESCE(t.customer_portal_enabled,0)=1 AND COALESCE(s.status,'trialing') IN ('active','trialing')`).get(parsed.data.tenantSlug,cpf)as any;
  const destinationMatches=row&&(channel==='email'?row.email&&row.email.toLowerCase()===parsed.data.email?.toLowerCase():row.phone&&normalizeBrazilPhone(row.phone)===normalizeBrazilPhone(parsed.data.phone||''));
  if(!destinationMatches)return res.status(202).json({message,channel});
  const token=channel==='whatsapp'?String(randomInt(100000,1000000)):newToken();
  const expires=new Date(Date.now()+(channel==='whatsapp'?10:30)*60_000).toISOString();
  db.transaction(()=>{
    db.prepare('UPDATE customer_password_reset_tokens SET used_at=CURRENT_TIMESTAMP WHERE account_id=? AND used_at IS NULL').run(row.accountId);
    db.prepare('INSERT INTO customer_password_reset_tokens(id,account_id,token_hash,expires_at,delivery_channel)VALUES(?,?,?,?,?)').run(randomUUID(),row.accountId,hashToken(token),expires,channel);
    if(channel==='whatsapp'){
      db.prepare("INSERT INTO customer_consents(id,tenant_id,customer_id,purpose,granted,source,document_version,privacy_version,ip_address,user_agent)VALUES(?,?,?,'security_whatsapp',1,'password_recovery',?,?,?,?)").run(randomUUID(),row.tenantId,row.customerId,TERMS_VERSION,PRIVACY_VERSION,req.ip||null,String(req.headers['user-agent']||'').slice(0,500)||null);
      db.prepare("INSERT INTO outbound_messages(id,tenant_id,recipient,channel,template,subject,message,scheduled_at)VALUES(?,?,?,'whatsapp','customer.password_reset_otp','Código de segurança',?,CURRENT_TIMESTAMP)").run(randomUUID(),row.tenantId,row.phone,token);
    }else{
      const webOrigin=((process.env.WEB_ORIGIN||'https://fidelizaplus.com.br').split(',')[0]||'https://fidelizaplus.com.br').trim();
      const url=`${webOrigin}/cliente/${encodeURIComponent(row.slug)}/recuperar?token=${encodeURIComponent(token)}`;
      db.prepare("INSERT INTO outbound_messages(id,tenant_id,recipient,channel,template,subject,message,scheduled_at)VALUES(?,?,?,'email','customer.password_reset',?,?,CURRENT_TIMESTAMP)").run(randomUUID(),row.tenantId,row.email,`Redefinição de senha · ${row.companyName}`,`Recebemos uma solicitação para redefinir a senha do seu programa de fidelidade ${row.companyName}. Use este link em até 30 minutos: ${url}\n\nSe você não solicitou a alteração, ignore esta mensagem. Sua senha atual continuará válida.`);
    }
  })();
  res.status(202).json({message,channel,...(!config.isProduction?{developmentToken:token}:{})});
});
portalRoutes.post('/customer/auth/reset-password',loginRateLimit,(req,res)=>{const p=z.object({token:z.string().min(20),password:z.string().min(10).regex(/[A-Z]/).regex(/[a-z]/).regex(/[0-9]/)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Use uma senha com ao menos 10 caracteres, incluindo maiúscula, minúscula e número'});const row=db.prepare("SELECT pr.id,pr.account_id accountId,c.cpf,t.slug FROM customer_password_reset_tokens pr JOIN customer_accounts ca ON ca.id=pr.account_id JOIN customers c ON c.id=ca.customer_id JOIN tenants t ON t.id=ca.tenant_id WHERE pr.token_hash=? AND pr.used_at IS NULL AND pr.expires_at>datetime('now')").get(hashToken(p.data.token))as any;if(!row){recordRateLimitedAttempt(req,'reset-token','invalid_reset_token');return res.status(400).json({error:'Link inválido, expirado ou já utilizado'})}db.transaction(()=>{db.prepare('UPDATE customer_accounts SET password_hash=? WHERE id=?').run(hashPassword(p.data.password),row.accountId);db.prepare('UPDATE customer_password_reset_tokens SET used_at=CURRENT_TIMESTAMP WHERE id=?').run(row.id);db.prepare('DELETE FROM customer_sessions WHERE account_id=?').run(row.accountId)})();clearLoginRateLimit(req,[row.cpf,row.slug],'/customer/auth/login');clearLoginRateLimit(req);session('customer_sessions','account_id',row.accountId,res,'fideliza_customer_session');res.json({ok:true})});
portalRoutes.post('/customer/auth/reset-password-code',loginRateLimit,(req,res)=>{const p=z.object({tenantSlug:z.string().min(2),cpf:z.string().min(11),code:z.string().regex(/^\d{6}$/),password:z.string().min(10).regex(/[A-Z]/).regex(/[a-z]/).regex(/[0-9]/)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Informe o código de seis dígitos e uma senha forte'});const account=db.prepare(`SELECT ca.id FROM customer_accounts ca JOIN customers c ON c.id=ca.customer_id JOIN tenants t ON t.id=ca.tenant_id WHERE t.slug=? AND c.cpf=? AND ca.active=1 AND c.deleted_at IS NULL`).get(p.data.tenantSlug,normalizeCpf(p.data.cpf))as{id:string}|undefined,row=account?db.prepare("SELECT id,account_id accountId FROM customer_password_reset_tokens WHERE account_id=? AND token_hash=? AND delivery_channel='whatsapp' AND used_at IS NULL AND expires_at>datetime('now') AND attempts<5 ORDER BY created_at DESC LIMIT 1").get(account.id,hashToken(p.data.code))as any:undefined;if(!row){if(account)db.prepare("UPDATE customer_password_reset_tokens SET attempts=attempts+1 WHERE id=(SELECT id FROM customer_password_reset_tokens WHERE account_id=? AND delivery_channel='whatsapp' AND used_at IS NULL ORDER BY created_at DESC LIMIT 1)").run(account.id);recordRateLimitedAttempt(req,normalizeCpf(p.data.cpf),'invalid_reset_code');return res.status(400).json({error:'Código inválido ou expirado'})}db.transaction(()=>{db.prepare('UPDATE customer_accounts SET password_hash=? WHERE id=?').run(hashPassword(p.data.password),row.accountId);db.prepare('UPDATE customer_password_reset_tokens SET used_at=CURRENT_TIMESTAMP WHERE id=?').run(row.id);db.prepare('DELETE FROM customer_sessions WHERE account_id=?').run(row.accountId)})();clearLoginRateLimit(req,[normalizeCpf(p.data.cpf),p.data.tenantSlug],'/customer/auth/login');clearLoginRateLimit(req);session('customer_sessions','account_id',row.accountId,res,'fideliza_customer_session');res.json({ok:true})});
portalRoutes.get('/customer/me',customerAuth,(req,res)=>res.json((req as any).customerAuth));
portalRoutes.get('/customer/dashboard',customerAuth,(req,res)=>{const a=(req as any).customerAuth,customer=db.prepare('SELECT id,name,email,phone,cpf,birth_date,points_balance,enrolled_at FROM customers WHERE id=? AND tenant_id=?').get(a.customerId,a.tenantId),ledger=db.prepare('SELECT id,points,reason,entry_type,created_at,expires_at FROM loyalty_ledger WHERE customer_id=? AND tenant_id=? ORDER BY created_at DESC LIMIT 6').all(a.customerId,a.tenantId),rewards=availableCustomerRewards(a.tenantId,a.customerId).slice(0,6),summary=db.prepare(`SELECT (SELECT COUNT(*) FROM sales WHERE tenant_id=? AND customer_id=? AND reversed_at IS NULL) purchases,(SELECT COALESCE(SUM(total_cents),0) FROM sales WHERE tenant_id=? AND customer_id=? AND reversed_at IS NULL) spentCents,(SELECT COUNT(*) FROM reward_redemptions WHERE tenant_id=? AND customer_id=?) redemptions,(SELECT COUNT(*) FROM customer_notifications WHERE tenant_id=? AND customer_id=? AND read_at IS NULL) unread`).get(a.tenantId,a.customerId,a.tenantId,a.customerId,a.tenantId,a.customerId,a.tenantId,a.customerId);res.json({customer,companyName:a.companyName,ledger,rewards,summary,vipTier:customerVipTier(a.tenantId,a.customerId)})});
portalRoutes.get('/customer/vip',customerAuth,(req,res)=>{const a=(req as any).customerAuth;res.json({tier:customerVipTier(a.tenantId,a.customerId)})});

function pageParams(req:Request){const page=Math.max(1,Number(req.query.page)||1),limit=Math.min(100,Math.max(5,Number(req.query.limit)||20));return{page,limit,offset:(page-1)*limit}}
portalRoutes.get('/customer/ledger',customerAuth,(req,res)=>{const a=(req as any).customerAuth,{page,limit,offset}=pageParams(req),type=String(req.query.type||''),from=String(req.query.from||''),to=String(req.query.to||'');let where='customer_id=? AND tenant_id=?',args:any[]=[a.customerId,a.tenantId];if(type){where+=' AND entry_type=?';args.push(type)}if(from){where+=' AND date(created_at)>=date(?)';args.push(from)}if(to){where+=' AND date(created_at)<=date(?)';args.push(to)}const total=(db.prepare(`SELECT COUNT(*) total FROM loyalty_ledger WHERE ${where}`).get(...args)as any).total,items=db.prepare(`SELECT id,points,reason,entry_type,created_at,expires_at,expired_at FROM loyalty_ledger WHERE ${where} ORDER BY created_at DESC LIMIT ? OFFSET ?`).all(...args,limit,offset);res.json({items,total,page,limit})});
portalRoutes.get('/customer/purchases',customerAuth,(req,res)=>{const a=(req as any).customerAuth,{page,limit,offset}=pageParams(req),search=String(req.query.search||''),from=String(req.query.from||''),to=String(req.query.to||'');let where='tenant_id=? AND customer_id=?',args:any[]=[a.tenantId,a.customerId];if(search){where+=' AND (order_number LIKE ? OR source LIKE ?)';args.push(`%${search}%`,`%${search}%`)}if(from){where+=' AND date(occurred_at)>=date(?)';args.push(from)}if(to){where+=' AND date(occurred_at)<=date(?)';args.push(to)}const total=(db.prepare(`SELECT COUNT(*) total FROM sales WHERE ${where}`).get(...args)as any).total,items=db.prepare(`SELECT id,total_cents,occurred_at,source,order_number,reversed_at,external_status FROM sales WHERE ${where} ORDER BY occurred_at DESC LIMIT ? OFFSET ?`).all(...args,limit,offset);res.json({items,total,page,limit})});
portalRoutes.get('/customer/rewards',customerAuth,(req,res)=>{const a=(req as any).customerAuth;res.json({items:availableCustomerRewards(a.tenantId,a.customerId),redemptions:db.prepare(`SELECT rr.id,rr.points_spent,rr.status,rr.redemption_code,rr.code_generated_at,rr.used_at,rr.order_number,rr.expires_at,rr.created_at,r.name reward_name,r.reward_type FROM reward_redemptions rr JOIN rewards r ON r.id=rr.reward_id WHERE rr.tenant_id=? AND rr.customer_id=? ORDER BY rr.created_at DESC`).all(a.tenantId,a.customerId),promotions:db.prepare(`SELECT id,name,multiplier,starts_at,ends_at FROM loyalty_promotions WHERE tenant_id=? AND active=1 AND datetime(ends_at)>=datetime('now') ORDER BY starts_at`).all(a.tenantId)})});
portalRoutes.post('/customer/rewards/:id/redeem',customerAuth,(req,res)=>{const a=(req as any).customerAuth;try{const redemption=db.transaction(()=>{const reward=db.prepare('SELECT * FROM rewards WHERE id=? AND tenant_id=? AND active=1').get(String(req.params.id),a.tenantId)as any,customer=db.prepare('SELECT points_balance FROM customers WHERE id=? AND tenant_id=?').get(a.customerId,a.tenantId)as any;if(!reward)throw new Error('NOT_FOUND');const today=businessDate(),tierRank=customerVipTier(a.tenantId,a.customerId)?.current?.rank??0;if(reward.valid_from&&today<reward.valid_from||reward.valid_until&&today>reward.valid_until)throw new Error('VALIDITY');if(reward.minimum_tier_rank&&tierRank<reward.minimum_tier_rank)throw new Error('TIER');if(customer.points_balance<reward.points_cost)throw new Error('BALANCE');const id=randomUUID();db.prepare("INSERT INTO reward_redemptions (id,tenant_id,reward_id,customer_id,points_spent,status,expires_at) VALUES (?,?,?,?,?,'confirmed',?)").run(id,a.tenantId,reward.id,a.customerId,reward.points_cost,reward.valid_until||null);db.prepare('UPDATE customers SET points_balance=points_balance-? WHERE id=? AND tenant_id=?').run(reward.points_cost,a.customerId,a.tenantId);db.prepare("INSERT INTO loyalty_ledger (id,tenant_id,customer_id,points,reason,entry_type) VALUES (?,?,?,?,?,'redemption')").run(randomUUID(),a.tenantId,a.customerId,-reward.points_cost,`Resgate: ${reward.name}`);db.prepare("INSERT INTO customer_notifications (id,tenant_id,customer_id,title,message,type) VALUES (?,?,?,?,?,'reward')").run(randomUUID(),a.tenantId,a.customerId,'Benefício resgatado',`${reward.name} foi resgatado com sucesso.`);return id})();res.status(201).json({id:redemption})}catch(e){const code=(e as Error).message;if(code==='NOT_FOUND')return res.status(404).json({error:'Benefício não encontrado'});if(code==='VALIDITY')return res.status(409).json({error:'Este benefício está fora do período de validade'});if(code==='TIER')return res.status(403).json({error:'Este benefício ainda não está disponível para o seu nível'});if(code==='BALANCE')return res.status(409).json({error:'Saldo de pontos insuficiente'});return res.status(409).json({error:'Não foi possível concluir o resgate'})}});
portalRoutes.post('/customer/redemptions/:id/use',customerAuth,(req,res)=>{const a=(req as any).customerAuth,id=String(req.params.id);try{const result=db.transaction(()=>{const current=db.prepare('SELECT id,status,redemption_code,expires_at FROM reward_redemptions WHERE id=? AND tenant_id=? AND customer_id=?').get(id,a.tenantId,a.customerId)as any;if(!current)throw new Error('NOT_FOUND');if(current.status==='used')throw new Error('USED');if(current.expires_at&&businessDate()>current.expires_at)throw new Error('EXPIRED');if(current.status==='ready_for_use'&&current.redemption_code)return{code:current.redemption_code,status:current.status};if(current.status!=='confirmed')throw new Error('STATUS');let code='';do{code=`FZ-${randomUUID().replaceAll('-','').slice(0,8).toUpperCase()}`}while(db.prepare('SELECT 1 FROM reward_redemptions WHERE redemption_code=?').get(code));db.prepare("UPDATE reward_redemptions SET status='ready_for_use',redemption_code=?,code_generated_at=CURRENT_TIMESTAMP WHERE id=? AND tenant_id=? AND customer_id=? AND status='confirmed'").run(code,id,a.tenantId,a.customerId);db.prepare("INSERT INTO customer_notifications(id,tenant_id,customer_id,title,message,type)VALUES(?,?,?,?,?,'reward')").run(randomUUID(),a.tenantId,a.customerId,'Cupom pronto para usar',`Informe o código ${code} no caixa. Ele é válido para uma única utilização até ${current.expires_at||'a data informada pela loja'}.`);return{code,status:'ready_for_use'}})();res.json(result)}catch(e){const code=(e as Error).message;if(code==='NOT_FOUND')return res.status(404).json({error:'Resgate não encontrado'});if(code==='USED')return res.status(409).json({error:'Este cupom já foi utilizado'});if(code==='EXPIRED')return res.status(409).json({error:'Este cupom está vencido'});return res.status(409).json({error:'Este resgate não pode ser utilizado'})}});
