portalRoutes.patch('/customer/profile',customerAuth,(req,res)=>{const a=(req as any).customerAuth,p=z.object({name:z.string().min(2),email:z.string().email(),phone:z.string().min(10),birthDate:z.string().optional().or(z.literal('')),address:z.string().max(160).optional(),city:z.string().max(80).optional(),state:z.string().max(2).optional(),postalCode:z.string().max(9).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Informe nome, e-mail válido e telefone'});if(db.prepare('SELECT 1 FROM customers WHERE tenant_id=? AND lower(email)=? AND id<>?').get(a.tenantId,p.data.email.toLowerCase(),a.customerId))return res.status(409).json({error:'Este e-mail já está em uso por outro participante desta loja'});db.prepare('UPDATE customers SET name=?,email=?,phone=?,birth_date=?,address=?,city=?,state=?,postal_code=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND tenant_id=?').run(p.data.name,p.data.email.toLowerCase(),p.data.phone.replace(/\D/g,''),p.data.birthDate||null,p.data.address||null,p.data.city||null,p.data.state||null,p.data.postalCode||null,a.customerId,a.tenantId);res.status(204).end()});
portalRoutes.put('/customer/password',customerAuth,(req,res)=>{const a=(req as any).customerAuth,p=z.object({currentPassword:z.string().min(8),newPassword:z.string().min(10)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'A nova senha deve ter ao menos 10 caracteres'});const account=db.prepare('SELECT password_hash FROM customer_accounts WHERE id=? AND tenant_id=?').get(a.accountId,a.tenantId)as any;if(!account||!verifyPassword(p.data.currentPassword,account.password_hash))return res.status(401).json({error:'Senha atual incorreta'});db.prepare('UPDATE customer_accounts SET password_hash=? WHERE id=? AND tenant_id=?').run(hashPassword(p.data.newPassword),a.accountId,a.tenantId);db.prepare('DELETE FROM customer_sessions WHERE account_id=? AND token_hash<>?').run(a.accountId,hashToken(req.cookies.fideliza_customer_session));res.status(204).end()});
