portalRoutes.post('/customer/support',customerAuth,(req,res)=>{const a=(req as any).customerAuth,p=z.object({subject:z.string().min(3),message:z.string().min(10),category:z.enum(['points','purchase','reward','account','privacy','other'])}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Descreva sua solicitação com mais detalhes'});const id=randomUUID(),ticketId=randomUUID(),priority=p.data.category==='privacy'?'high':'medium',slaHours=priority==='high'?8:24,slaDueAt=new Date(Date.now()+slaHours*3600000).toISOString();db.transaction(()=>{db.prepare('INSERT INTO customer_support_requests (id,tenant_id,customer_id,subject,message,category,support_ticket_id) VALUES (?,?,?,?,?,?,?)').run(id,a.tenantId,a.customerId,p.data.subject,p.data.message,p.data.category,ticketId);db.prepare("INSERT INTO support_tickets(id,tenant_id,subject,description,priority,sla_due_at,source,customer_id,customer_request_id,category) VALUES(?,?,?,?,?,?,'customer',?,?,?)").run(ticketId,a.tenantId,p.data.subject,p.data.message,priority,slaDueAt,a.customerId,id,p.data.category);db.prepare("INSERT INTO support_ticket_events(id,ticket_id,tenant_id,actor_type,actor_id,action,message)VALUES(?,?,?,?,?,'created',?)").run(randomUUID(),ticketId,a.tenantId,'customer',a.customerId,p.data.message)})();res.status(201).json({id,ticketId,slaDueAt})});

portalRoutes.get('/customer/store-offers',customerAuth,(req,res)=>{const a=(req as any).customerAuth;releaseExpiredOfferReservations(a.tenantId);res.json({items:db.prepare(`SELECT o.id,o.name,o.description,o.product_sku productSku,o.price_cents priceCents,o.original_price_cents originalPriceCents,o.image_data imageData,o.stock,o.starts_at startsAt,o.ends_at endsAt,o.payment_type paymentType,o.payment_instructions paymentInstructions,o.payment_url paymentUrl,
  i.id reservationId,i.status reservationStatus,i.reservation_code reservationCode,COALESCE(i.price_cents,o.price_cents) reservedPriceCents,i.reserved_at reservedAt,i.expires_at expiresAt,i.paid_at paidAt,i.order_number orderNumber
  FROM store_offers o LEFT JOIN offer_interests i ON i.offer_id=o.id AND i.customer_id=? WHERE o.tenant_id=? AND o.status='published' AND (o.starts_at IS NULL OR datetime(o.starts_at)<=datetime('now')) AND (o.ends_at IS NULL OR datetime(o.ends_at)>=datetime('now')) ORDER BY o.updated_at DESC`).all(a.customerId,a.tenantId),reservations:db.prepare(`SELECT i.id,i.offer_id offerId,i.status,i.reservation_code reservationCode,COALESCE(i.price_cents,o.price_cents) priceCents,i.reserved_at reservedAt,i.expires_at expiresAt,i.paid_at paidAt,i.order_number orderNumber,o.name offerName,o.payment_type paymentType,o.payment_instructions paymentInstructions,o.payment_url paymentUrl FROM offer_interests i JOIN store_offers o ON o.id=i.offer_id WHERE i.tenant_id=? AND i.customer_id=? ORDER BY i.updated_at DESC`).all(a.tenantId,a.customerId)})});
portalRoutes.post('/customer/store-offers/:id/redeem',customerAuth,(req,res)=>{const a=(req as any).customerAuth;releaseExpiredOfferReservations(a.tenantId);const p=z.object({message:z.string().max(500).optional(),preferredContact:z.enum(['whatsapp','email','phone']).default('whatsapp')}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Dados da reserva inválidos'});try{const result=db.transaction(()=>{const offer=db.prepare(`SELECT * FROM store_offers WHERE id=? AND tenant_id=? AND status='published' AND price_cents>0 AND (starts_at IS NULL OR datetime(starts_at)<=datetime('now')) AND (ends_at IS NULL OR datetime(ends_at)>=datetime('now'))`).get(String(req.params.id),a.tenantId)as any;if(!offer)throw new Error('NOT_FOUND');const existing=db.prepare('SELECT * FROM offer_interests WHERE offer_id=? AND customer_id=?').get(offer.id,a.customerId)as any;if(existing&&['reserved','converted'].includes(existing.status))return{id:existing.id,status:existing.status,code:existing.reservation_code,priceCents:existing.price_cents||offer.price_cents,paymentType:offer.payment_type,paymentInstructions:offer.payment_instructions,paymentUrl:offer.payment_url};if(offer.stock!==null&&offer.stock<=0)throw new Error('STOCK');let code='';do{code=`OF-${randomUUID().replaceAll('-','').slice(0,8).toUpperCase()}`}while(db.prepare('SELECT 1 FROM offer_interests WHERE reservation_code=?').get(code));const id=existing?.id||randomUUID(),expiresAt=new Date(Date.now()+48*3600000).toISOString();if(existing)db.prepare("UPDATE offer_interests SET status='reserved',message=?,preferred_contact=?,reservation_code=?,price_cents=?,reserved_at=CURRENT_TIMESTAMP,expires_at=?,paid_at=NULL,payment_method=NULL,order_number=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=? AND tenant_id=?").run(p.data.message||null,p.data.preferredContact,code,offer.price_cents,expiresAt,id,a.tenantId);else db.prepare("INSERT INTO offer_interests(id,tenant_id,offer_id,customer_id,status,message,preferred_contact,reservation_code,price_cents,reserved_at,expires_at)VALUES(?,?,?,?,'reserved',?,?,?,?,CURRENT_TIMESTAMP,?)").run(id,a.tenantId,offer.id,a.customerId,p.data.message||null,p.data.preferredContact,code,offer.price_cents,expiresAt);if(offer.stock!==null)db.prepare('UPDATE store_offers SET stock=stock-1,updated_at=CURRENT_TIMESTAMP WHERE id=? AND tenant_id=? AND stock>0').run(offer.id,a.tenantId);db.prepare("INSERT INTO customer_notifications(id,tenant_id,customer_id,title,message,type)VALUES(?,?,?,?,?,'offer')").run(randomUUID(),a.tenantId,a.customerId,'Oferta reservada',`${offer.name} foi reservado por ${(offer.price_cents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}. Informe o código ${code} à loja e faça o pagamento diretamente a ela.`);return{id,status:'reserved',code,priceCents:offer.price_cents,expiresAt,paymentType:offer.payment_type,paymentInstructions:offer.payment_instructions,paymentUrl:offer.payment_url}})();res.status(201).json(result)}catch(e){const reason=(e as Error).message;if(reason==='NOT_FOUND')return res.status(404).json({error:'Oferta indisponível'});if(reason==='STOCK')return res.status(409).json({error:'Esta oferta está esgotada'});return res.status(409).json({error:'Não foi possível reservar a oferta'})}});
portalRoutes.post('/customer/offer-reservations/:id/cancel',customerAuth,(req,res)=>{const a=(req as any).customerAuth,id=String(req.params.id);try{db.transaction(()=>{const reservation=db.prepare('SELECT i.*,o.stock FROM offer_interests i JOIN store_offers o ON o.id=i.offer_id WHERE i.id=? AND i.tenant_id=? AND i.customer_id=?').get(id,a.tenantId,a.customerId)as any;if(!reservation)throw new Error('NOT_FOUND');if(reservation.status!=='reserved')throw new Error('STATUS');db.prepare("UPDATE offer_interests SET status='canceled',updated_at=CURRENT_TIMESTAMP WHERE id=? AND tenant_id=? AND customer_id=?").run(id,a.tenantId,a.customerId);if(reservation.stock!==null)db.prepare('UPDATE store_offers SET stock=stock+1,updated_at=CURRENT_TIMESTAMP WHERE id=? AND tenant_id=?').run(reservation.offer_id,a.tenantId)})();res.status(204).end()}catch(e){if((e as Error).message==='NOT_FOUND')return res.status(404).json({error:'Reserva não encontrada'});return res.status(409).json({error:'Somente reservas aguardando pagamento podem ser canceladas'})}});
