portalRoutes.post('/platform/auth/login',loginRateLimit,(req,res)=>{
  const p=z.object({email:z.string().email().max(254),password:z.string().min(10).max(128),totpCode:z.string().regex(/^\d{6}$/).optional()}).safeParse(req.body);
  if(!p.success)return res.status(400).json({error:'Dados inválidos'});
  let admin=db.prepare('SELECT * FROM platform_admins WHERE lower(email)=lower(?) AND active=1').get(p.data.email)as any;
  const bootstrapAllowed=!config.isProduction||process.env.PLATFORM_ADMIN_BOOTSTRAP_ENABLED==='true';
  if(!admin&&bootstrapAllowed&&process.env.PLATFORM_ADMIN_EMAIL&&process.env.PLATFORM_ADMIN_PASSWORD&&secureStringEqual(p.data.email.toLowerCase(),process.env.PLATFORM_ADMIN_EMAIL.toLowerCase())&&secureStringEqual(p.data.password,process.env.PLATFORM_ADMIN_PASSWORD)){const id=randomUUID();db.prepare('INSERT INTO platform_admins (id,name,email,password_hash) VALUES (?,?,?,?)').run(id,process.env.PLATFORM_ADMIN_NAME||'Administrador Fidelizei',process.env.PLATFORM_ADMIN_EMAIL,hashPassword(process.env.PLATFORM_ADMIN_PASSWORD));admin=db.prepare('SELECT * FROM platform_admins WHERE id=?').get(id)}
  if(!admin||!verifyPassword(p.data.password,admin.password_hash)){recordAccess(req,'platform',p.data.email,false,null,'Credencial inválida');return res.status(401).json({error:'E-mail ou senha inválidos'})}
  if(admin.two_factor_enabled&&(!p.data.totpCode||!admin.two_factor_secret_encrypted||!verifyTotp(decryptTotp(admin.two_factor_secret_encrypted),p.data.totpCode))){recordAccess(req,'platform',p.data.email,false,null,'MFA ausente ou inválido');return res.status(401).json({error:p.data.totpCode?'Código do autenticador inválido':'Código do autenticador necessário'})}
  clearLoginRateLimit(req);db.prepare('UPDATE platform_admins SET last_login_at=CURRENT_TIMESTAMP WHERE id=?').run(admin.id);recordAccess(req,'platform',admin.id,true);createSecureSession('platform',admin.id,req,res);res.json({name:admin.name,twoFactorEnabled:Boolean(admin.two_factor_enabled)});
});
portalRoutes.get('/platform/me/security',platformAuth,(req,res)=>res.json({twoFactorEnabled:Boolean((req as any).platformAuth.twoFactorEnabled)}));
portalRoutes.post('/platform/me/security/2fa/setup',platformAuth,(req,res)=>{const a=(req as any).platformAuth,secret=newTotpSecret();db.prepare('UPDATE platform_admins SET two_factor_pending_secret_encrypted=? WHERE id=?').run(encryptTotp(secret),a.adminId);res.json({secret,uri:totpUri(secret,a.email)})});
portalRoutes.post('/platform/me/security/2fa/confirm',platformAuth,(req,res)=>{const p=z.object({code:z.string().regex(/^\d{6}$/)}).safeParse(req.body),a=(req as any).platformAuth,admin=db.prepare('SELECT two_factor_pending_secret_encrypted FROM platform_admins WHERE id=?').get(a.adminId)as any;if(!p.success||!admin?.two_factor_pending_secret_encrypted||!verifyTotp(decryptTotp(admin.two_factor_pending_secret_encrypted),p.data.code))return res.status(400).json({error:'Código inválido'});db.prepare('UPDATE platform_admins SET two_factor_secret_encrypted=two_factor_pending_secret_encrypted,two_factor_pending_secret_encrypted=NULL,two_factor_enabled=1 WHERE id=?').run(a.adminId);db.prepare("INSERT INTO platform_audit_logs(id,admin_id,action,entity_type,entity_id,ip,metadata)VALUES(?,?,?,'platform_admin',?,?,?)").run(randomUUID(),a.adminId,'mfa.enabled',a.adminId,req.ip,'{}');res.status(204).end()});
portalRoutes.delete('/platform/me/security/2fa',platformAuth,(req,res)=>{const p=z.object({password:z.string().min(10).max(128),code:z.string().regex(/^\d{6}$/)}).safeParse(req.body),a=(req as any).platformAuth,admin=db.prepare('SELECT password_hash,two_factor_secret_encrypted FROM platform_admins WHERE id=?').get(a.adminId)as any;if(!p.success||!admin?.two_factor_secret_encrypted||!verifyPassword(p.data.password,admin.password_hash)||!verifyTotp(decryptTotp(admin.two_factor_secret_encrypted),p.data.code))return res.status(400).json({error:'Senha ou código inválidos'});db.transaction(()=>{db.prepare('UPDATE platform_admins SET two_factor_enabled=0,two_factor_secret_encrypted=NULL,two_factor_pending_secret_encrypted=NULL WHERE id=?').run(a.adminId);db.prepare('DELETE FROM platform_sessions WHERE admin_id=? AND token_hash<>?').run(a.adminId,hashToken(req.cookies.fideliza_platform_session));db.prepare("INSERT INTO platform_audit_logs(id,admin_id,action,entity_type,entity_id,ip,metadata)VALUES(?,?,?,'platform_admin',?,?,?)").run(randomUUID(),a.adminId,'mfa.disabled',a.adminId,req.ip,'{}')})();res.status(204).end()});
portalRoutes.get('/platform/me',platformAuth,(req,res)=>res.json({...(req as any).platformAuth,twoFactorEnabled:Boolean((req as any).platformAuth.twoFactorEnabled),mfaRequired:platformMfaRequired()}));
portalRoutes.put('/platform/me/password',platformAuth,(req,res)=>{const p=z.object({currentPassword:z.string().min(10),newPassword:z.string().min(12).regex(/[A-Z]/).regex(/[a-z]/).regex(/[0-9]/).regex(/[^A-Za-z0-9]/)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'A nova senha deve ter ao menos 12 caracteres, maiúscula, minúscula, número e símbolo'});const a=(req as any).platformAuth,admin=db.prepare('SELECT password_hash FROM platform_admins WHERE id=?').get(a.adminId)as any;if(!admin||!verifyPassword(p.data.currentPassword,admin.password_hash))return res.status(400).json({error:'Senha atual incorreta'});db.transaction(()=>{db.prepare('UPDATE platform_admins SET password_hash=? WHERE id=?').run(hashPassword(p.data.newPassword),a.adminId);db.prepare('DELETE FROM platform_sessions WHERE admin_id=? AND token_hash<>?').run(a.adminId,hashToken(req.cookies.fideliza_platform_session))})();res.status(204).end()});
portalRoutes.put('/platform/me/profile',platformAuth,(req,res)=>{const p=z.object({name:z.string().min(2).max(120),email:z.string().email(),currentPassword:z.string().min(10),newPassword:z.string().min(12).regex(/[A-Z]/).regex(/[a-z]/).regex(/[0-9]/).regex(/[^A-Za-z0-9]/)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Revise nome, e-mail e senha forte'});const a=(req as any).platformAuth,admin=db.prepare('SELECT password_hash FROM platform_admins WHERE id=?').get(a.adminId)as any;if(!admin||!verifyPassword(p.data.currentPassword,admin.password_hash))return res.status(400).json({error:'Senha atual incorreta'});try{db.transaction(()=>{db.prepare('UPDATE platform_admins SET name=?,email=?,password_hash=? WHERE id=?').run(p.data.name,p.data.email.toLowerCase(),hashPassword(p.data.newPassword),a.adminId);db.prepare('DELETE FROM platform_sessions WHERE admin_id=? AND token_hash<>?').run(a.adminId,hashToken(req.cookies.fideliza_platform_session));db.prepare("INSERT INTO platform_audit_logs(id,admin_id,action,entity_type,entity_id,ip,metadata)VALUES(?,?,?,'platform_admin',?,?,?)").run(randomUUID(),a.adminId,'profile.update',a.adminId,req.ip,JSON.stringify({email:p.data.email.toLowerCase()}))})();res.json({name:p.data.name,email:p.data.email.toLowerCase(),role:a.role})}catch(error){if(String((error as Error).message).includes('UNIQUE constraint failed'))return res.status(409).json({error:'E-mail já utilizado por outro administrador'});throw error}});
portalRoutes.get('/platform/dashboard',platformAuth,(_req,res)=>{const kpis=db.prepare(`SELECT COUNT(*) tenants,SUM(CASE WHEN s.status IN ('active','trialing') THEN 1 ELSE 0 END) activeSubscriptions,COALESCE(SUM(CASE WHEN s.status='active' THEN s.monthly_price_cents ELSE 0 END),0) mrrCents,(SELECT COUNT(*) FROM customers WHERE deleted_at IS NULL) consumers FROM tenants t LEFT JOIN subscriptions s ON s.tenant_id=t.id`).get(),companies=db.prepare(`SELECT t.id,t.name,t.slug,t.created_at,s.plan_code planCode,s.status,s.monthly_price_cents monthlyPriceCents,s.current_period_end currentPeriodEnd,(SELECT COUNT(*) FROM users WHERE tenant_id=t.id) users,(SELECT COUNT(*) FROM customers WHERE tenant_id=t.id AND deleted_at IS NULL) customers FROM tenants t LEFT JOIN subscriptions s ON s.tenant_id=t.id ORDER BY t.created_at DESC`).all();res.json({kpis,companies,plans:[{code:'pilot',name:'Piloto'},{code:'essential',name:'Essencial'},{code:'growth',name:'Crescimento'},{code:'professional',name:'Profissional'}]})});
portalRoutes.patch('/platform/subscriptions/:tenantId',platformAuth,(req,res)=>{const p=z.object({planCode:z.enum(['pilot','essential','growth','professional']),status:z.enum(['trialing','active','past_due','suspended','canceled']),monthlyPriceCents:z.number().int().min(0),currentPeriodEnd:z.string().optional().or(z.literal(''))}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Assinatura inválida'});db.prepare(`INSERT INTO subscriptions (id,tenant_id,plan_code,status,monthly_price_cents,current_period_end) VALUES (?,?,?,?,?,?) ON CONFLICT(tenant_id) DO UPDATE SET plan_code=excluded.plan_code,status=excluded.status,monthly_price_cents=excluded.monthly_price_cents,current_period_end=excluded.current_period_end,updated_at=CURRENT_TIMESTAMP`).run(randomUUID(),String(req.params.tenantId),p.data.planCode,p.data.status,p.data.monthlyPriceCents,p.data.currentPeriodEnd||null);res.status(204).end()});portalRoutes.post('/platform/auth/logout',platformAuth,(req,res)=>{db.prepare('DELETE FROM platform_sessions WHERE token_hash=?').run(hashToken(req.cookies.fideliza_platform_session));res.clearCookie('fideliza_platform_session');res.status(204).end()});
